const out = [];
for (const item of $input.all()) {
  const fileUrl = item.json.File || '';
  const match = fileUrl.match(/\/d\/([a-zA-Z0-9_-]+)/);
  const docId = match ? match[1] : null;
  out.push({
    json: {
      ...item.json,
      docId,
      prompt: item.json['Image Prompt'],
    },
  });
}
return out;

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const row = $('Get parent folder').all()[i]?.json || {};
  const targetFolderId = row.parents?.[0];
  const filename = `image_${i + 1}.png`;

  if (item.binary?.data) {
    out.push({
      json: { filename, targetFolderId },
      binary: { data: { ...item.binary.data, fileName: filename, mimeType: 'image/png' } },
    });
    continue;
  }

  const b64 = item.json?.data?.[0]?.b64_json;
  if (!b64) continue; // OpenAI call failed or returned no image; nothing to upload
  const buffer = Buffer.from(b64, 'base64');
  out.push({
    json: { filename, targetFolderId },
    binary: { data: await this.helpers.prepareBinaryData(buffer, filename, 'image/png') },
  });
}
return out;
